package com.u1.slicer.data

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class NightPrintGcodeAuditTest {
    private fun temp(text: String): File = File.createTempFile("nightprint-test-", ".gcode").apply {
        writeText(text.trimIndent())
        deleteOnExit()
    }

    private val valid = """
        ; generated by Snapmaker Orca
        M1002 set_filament_type:TPU
        M140 S50
        M109 S140
        M1002 set_filament_type:UNKNOWN
        M109 S225
        M1002 set_filament_type:TPU
        M104 S225
        ; filament_type = TPU
        ; printer_model = Bambu Lab A1 mini
        ; nozzle_temperature_initial_layer = 225
        ;LAYER_CHANGE
        ;Z:0.2
        G1 X5 Y5 E0.5 F1800
    """

    private fun audit(text: String) = NightPrintGcodeAudit.inspect(temp(text), "TPU", 225, 50)

    @Test fun acceptsValidTpuSample() = assertTrue(audit(valid).passed)
    @Test fun ignoresUnknownStartupMaterial() = assertTrue(audit(valid).passed)
    @Test fun acceptsIndentedMetadataComments() {
        val withWhitespace = valid
            .replace("; filament_type = TPU", "  ; filament_type = TPU")
            .replace("; printer_model = Bambu Lab A1 mini", "  ; printer_model = Bambu Lab A1 mini")
            .replace("; nozzle_temperature_initial_layer = 225", "  ; nozzle_temperature_initial_layer = 225")
        assertTrue(audit(withWhitespace).passed)
    }
    @Test fun rejectsPlaInExecutableHeader() {
        val result = audit(valid.replace("M1002 set_filament_type:TPU", "M1002 set_filament_type:PLA"))
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("Material mismatch") })
    }
    @Test fun rejectsPlaInMetadata() {
        val result = audit(valid.replace("; filament_type = TPU", "; filament_type = PLA"))
        assertFalse(result.passed)
    }
    @Test fun rejectsWrongMachine() =
        assertFalse(audit(valid.replace("Bambu Lab A1 mini", "Snapmaker U1")).passed)
    @Test fun rejectsMissingPrinterTag() =
        assertFalse(audit(valid.replace("; printer_model = Bambu Lab A1 mini", "")).passed)
    @Test fun rejectsNozzleMismatch() =
        assertFalse(audit(valid.replace("nozzle_temperature_initial_layer = 225", "nozzle_temperature_initial_layer = 235")).passed)
    @Test fun rejectsBedMismatch() =
        assertFalse(audit(valid.replace("M140 S50", "M140 S60")).passed)
    @Test fun rejectsMissingMaterialIdentity() =
        assertFalse(audit(valid.replace("M1002 set_filament_type:TPU", "").replace("; filament_type = TPU", "")).passed)
    @Test fun rejectsHiddenHotendOverTemperatureEvenWhenExpectedCommandExists() {
        assertFalse(audit(valid + "\nM104 S270").passed)
    }
    @Test fun rejectsHiddenBedOverTemperatureEvenWhenExpectedCommandExists() {
        assertFalse(audit(valid + "\nM140 S90").passed)
    }
    @Test fun allowsLowerStartupNozzleTemperature() =
        assertTrue(audit(valid.replace("M109 S140", "M109 S150")).passed)

    @Test fun detectsRealisticTpuPurgeAndRequiresExplicitApproval() {
        val purge = valid.replace(";LAYER_CHANGE", "M104 S250\nM109 S250\n;LAYER_CHANGE")
        val blocked = audit(purge)
        assertFalse(blocked.passed)
        assertTrue(blocked.requiresStartupHeatApproval)
        assertTrue(blocked.errors.any { it.contains("explicit approval") })
        val approved = NightPrintGcodeAudit.inspect(temp(purge), "TPU", 225, 50,
            startupHeatApproved = true)
        assertTrue(approved.passed)
        assertTrue(approved.warnings.any { it.contains("250") })
        assertEquals(250, approved.startupNozzlePeakC)
    }

    @Test fun permitsHeatDialogOnlyForConsentAlone() {
        val purge = valid.replace(";LAYER_CHANGE", "M104 S250\n;LAYER_CHANGE")
        val pending = audit(purge)
        assertTrue(NightPrintGcodeAudit.canRequestStartupHeatApproval(pending))
        val approved = NightPrintGcodeAudit.inspect(
            temp(purge), "TPU", 225, 50, startupHeatApproved = true
        )
        assertTrue(approved.passed)
        assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(approved))
    }

    @Test fun neverOffersHeatApprovalForMaterialOrMachineMismatch() {
        val purge = valid.replace(";LAYER_CHANGE", "M104 S250\n;LAYER_CHANGE")
        assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(
            audit(purge.replace("; filament_type = TPU", "; filament_type = PLA"))
        ))
        assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(
            audit(purge.replace("Bambu Lab A1 mini", "Snapmaker U1"))
        ))
    }

    @Test fun neverOffersHeatApprovalForPostLayerOverheat() {
        val unsafe = valid.replace(";LAYER_CHANGE", "M104 S250\n;LAYER_CHANGE") + "\nM104 S250"
        assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(audit(unsafe)))
    }

    @Test fun acceptsToolSelectedNozzleTargetAndDecimalInteger() {
        val gcode = valid.replace("M104 S225", "M104 T0 S225.0")
        assertTrue(audit(gcode).passed)
    }

    @Test fun acceptsGcodeWaitRCommands() {
        val gcode = valid.replace("M109 S225", "M109 R225")
            .replace("M140 S50", "M190 R50")
        assertTrue(audit(gcode).passed)
    }

    @Test fun rejectsOverheatWhenToolSelectorPrecedesTemperature() {
        val result = audit(valid + "\nM104 T0 S250")
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("AFTER layer") })
    }

    @Test fun rejectsTooHotStartupWithToolSelectorEvenWhenApproved() {
        val gcode = valid.replace(";LAYER_CHANGE", "M104 T0 S270\n;LAYER_CHANGE")
        val result = NightPrintGcodeAudit.inspect(temp(gcode), "TPU", 225, 50, true)
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("material cap") })
    }

    @Test fun rejectsBedOverheatWhenHeaterSelectorPrecedesTemperature() {
        val result = audit(valid + "\nM140 P0 S90")
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("bed temperature") })
    }

    @Test fun rejectsUnknownTemperatureCommandInsteadOfIgnoringIt() {
        val result = audit(valid + "\nM104 T0 Q270")
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("Unrecognized or unsafe temperature") })
    }

    @Test fun rejectsFractionalTemperatureCommandInsteadOfTruncatingIt() {
        val result = audit(valid + "\nM104 S225.5")
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("Unrecognized or unsafe temperature") })
    }

    @Test fun rejectsUnexpected270cDuringStartupEvenWithApproval() {
        val invalid = valid.replace(";LAYER_CHANGE", "M104 S270\n;LAYER_CHANGE")
        assertFalse(NightPrintGcodeAudit.inspect(temp(invalid), "TPU", 225, 50, true).passed)
    }

    @Test fun rejects250cAfterFirstLayerEvenWithApproval() {
        val badPrint = valid + "\nM104 S250"
        val result = NightPrintGcodeAudit.inspect(temp(badPrint), "TPU", 225, 50, true)
        assertFalse(result.passed)
        assertTrue(result.errors.any { it.contains("AFTER layer") })
    }

    @Test fun rejectsMissingLayerMarker() {
        val bad = valid.replace(";LAYER_CHANGE", ";MISSING_LAYER_MARKER")
        assertFalse(audit(bad).passed)
    }

    @Test fun rejectsEmptyGcode() = assertFalse(audit("").passed)
    private val petg = valid.replace("TPU", "PETG").replace("225", "235").replace("S50", "S65")
    private fun petgAudit(code: String, approved: Boolean = false) =
        NightPrintGcodeAudit.inspect(temp(code), "PETG", 235, 65, approved)
    private val petgPurge = petg.replace(";LAYER_CHANGE",
        "M104 S250\nM109 S250\nM104 S240\nM109 S235\n;LAYER_CHANGE")

    @Test fun petg235PurgeRequiresExplicitReviewAndReturnToTarget() {
        val pending = petgAudit(petgPurge)
        assertFalse(pending.passed)
        assertTrue(NightPrintGcodeAudit.canRequestStartupHeatApproval(pending))
        assertTrue(petgAudit(petgPurge, true).passed)
    }
    @Test fun petgRejectsPurgeWithoutReturnEvenWithConsent() {
        val bad = petgPurge.replace("M109 S235\n;LAYER_CHANGE", ";LAYER_CHANGE")
        assertFalse(petgAudit(bad, true).passed)
        assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(petgAudit(bad)))
    }
    @Test fun petgRejectsHeatingAgainAfterReturn() {
        val bad = petgPurge.replace(";LAYER_CHANGE", "M104 S240\n;LAYER_CHANGE")
        assertFalse(petgAudit(bad, true).passed)
    }
    @Test fun petgRejectsUnknownStartupHeatAndAboveCeiling() {
        for (badTemp in listOf(245, 251, 270)) {
            val bad = petgPurge.replace("M104 S250", "M104 S" + badTemp)
            assertFalse(petgAudit(bad, true).passed)
            assertFalse(NightPrintGcodeAudit.canRequestStartupHeatApproval(petgAudit(bad)))
        }
    }
    @Test fun petgRejectsLayerOverheatEvenWithConsent() {
        assertFalse(petgAudit(petgPurge + "\nM104 T0 S240", true).passed)
    }
    @Test fun petgRejectsWrongMaterialBedAndMachineEvenWithConsent() {
        for (bad in listOf(petgPurge.replace("PETG", "PLA"),
            petgPurge.replace("S65","S75"),
            petgPurge.replace("Bambu Lab A1 mini","Bambu Lab A1"))) {
            assertFalse(petgAudit(bad, true).passed)
        }
    }
}
